//! Data generated by scripts in `electricity/scripts/`; see each submodule.

mod unicode_nonprintable_ranges;

/// Whether `c` is printable per Python's `str.isprintable()`: not in
/// Unicode category Cc/Cf/Cs/Co/Cn/Zl/Zp/Zs, except the ASCII space.
pub(crate) fn is_py_printable(c: char) -> bool {
    let cp = c as u32;
    unicode_nonprintable_ranges::NONPRINTABLE_RANGES
        .binary_search_by(|&(lo, hi)| {
            if cp < lo {
                std::cmp::Ordering::Greater
            } else if cp > hi {
                std::cmp::Ordering::Less
            } else {
                std::cmp::Ordering::Equal
            }
        })
        .is_err()
}
